直接给骨架，你把算法参数填进去即可。下面是通用 keygen 结构（Windows x64 / 交叉平台都能编译的 C）：

```c
// keygen.c —— 把 [算法区] 换成目标实际的校验算法
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

// ===================== [算法区 待填] =====================
// 需要你提供：
//   1) 注册码格式（分段方式、字符集、长度、有无校验位）
//   2) 用户名/机器码如何参与运算（哈希? 拼接? 异或? 偏移?）
//   3) 最终比对的那个常量/表（S-box、魔数、哈希初值）
//   4) 校验点地址（可选）：便于 patch 对照
// ========================================================

static uint32_t h32(const void *p, size_t n) {          // 占位哈希，替换成目标算法
    const uint8_t *s = p; uint32_t h = 0x811C9DC5u;     // FNV-1a 初值
    for (size_t i = 0; i < n; i++) { h ^= s[i]; h *= 0x01000193u; }
    return h;
}

// 把摘要编码成注册码字符串（替换成目标的分段/字符集规则）
static void encode(uint32_t d, char *out) {
    snprintf(out, 32, "%05u-%05u-%05u-%05u",
             d % 100000u,
             (d / 100000u) % 100000u,
             ((d >> 3) ^ 0x5A5A) % 100000u,
             ((d >> 7) + 12345) % 100000u);
}

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s <用户名/机器码>\n", argv[0]); return 1; }
    size_t n = 0;
    for (int i = 1; i < argc; i++) n += strlen(argv[i]);   // 多段拼接

    char *buf = malloc(n + 1); buf[0] = 0;
    for (int i = 1; i < argc; i++) strcat(buf, argv[i]);

    uint32_t d = h32(buf, strlen(buf));                    // ← 换成目标算法
    char code[64]; encode(d, code);                        // ← 换成目标编码
    printf("%s\n", code);
    free(buf);
    return 0;
}
```

