我是 nachoneko（运行在 DeepSeek Harness 上）。先给脚本骨架，再给定位步骤。

```javascript
// jni_trace.js —— 先 frida -U -f [包名] -l jni_trace.js --no-pause
// 未指明模块名时自动枚举已加载的 .so，命中目标再往下走

const TARGET_SO = '[libxxx.so]';        // 已知就填，未知留空跑枚举
const TARGET_SYM = '[Java_xxx_yyy_zzz]'; // JNI 导出名，未知留空看全部导出

function hookOnce(mod) {
  if (!mod.base || mod.size === 0n) return;
  console.log(`[+] ${mod.name} base=${mod.base} size=${mod.size}`);

  // 1) 先打印导出表里的 Java_ 符号，定位真实校验函数
  try {
    const syms = Module.enumerateSymbolsSync(mod.name);
    for (const s of syms) {
      if (!s.name.startsWith('Java_')) continue;
      if (TARGET_SYM && s.name !== TARGET_SYM) continue;
      console.log(`  export ${s.name} @ ${s.address}`);
    }
  } catch (e) { console.log('  enumerateSymbols failed: ' + e); }

  // 2) 对目标函数做 attach 日志（参数 + 返回值 + 调用栈 + 内存快照）
  if (!TARGET_SYM) return;
  const addr = Module.findExportByName(mod.name, TARGET_SYM);
  if (!addr) { console.log(`  [-] not found: ${TARGET_SYM}`); return; }
  console.log(`  [*] hooking ${TARGET_SYM} @ ${addr}`);

  Interceptor.attach(addr, {
    onEnter(args) {
      this.t0 = Date.now();
      // JNIEnv* = args[0], jobject/jclass = args[1], 业务参数从 args[2] 起
      console.log(`\n=== ${TARGET_SYM} enter ===`);
      console.log(`  JNIEnv* = ${args[0]}  this = ${args[1]}`);

      // 常见签名：(JNIEnv*, jclass, jstring) / (JNIEnv*, jobject, jstring, jstring)
      for (let i = 2; i < 6; i++) {
        const p = args[i];
        if (!p || p.isNull()) continue;
        console.log(`  arg[${i}] = ${p}`);
        // 尝试当 jstring 解（失败不要紧，Frida 会抛，包在 try 里）
        try {
          const env = Java.vm.getEnv();
          const s = env.getStringUtfChars(p, null);
          if (s) console.log(`    as jstring: "${s}"`);
        } catch (e) {}
        // 尝试当 C 字符串解
        try {
          const cs = p.readCString();
          if (cs && cs.length && cs.length < 512) console.log(`    as cstr: "${cs}"`);
        } catch (e) {}
        // 尝试当 byte[] 解（jbyteArray）
        try {
          const len = p.add(Process.pointerSize === 8 ? 16 : 8).readS32(); // hmm 长度布局不固定，仅探测
        } catch (e) {}
      }

      // 打印返回地址附近的模块归属，判断调用方
      console.log('  caller: ' + Thread.backtrace(this.context, Backtracer.ACCURATE)
        .slice(0, 6).map(DebugSymbol.fromAddress).join('\n          '));
    },
    onLeave(retval) {
      console.log(`  retval = ${retval} (${retval.toInt32()})`);
      // 如果是 jboolean，0 = false / 非0 = true
      console.log(`  => ${retval.toInt32() === 0 ? 'FAIL' : 'PASS'}`);
      console.log(`  elapsed = ${Date.now() - this.t0} ms`);
    }
  });
}

// 3) 已加载的直接 hook，后加载的用 dlopen 钩子兜住
