先给你可用的 Frida 脚本骨架，按 `Java_<包名>_<类名>_<方法名>` 导出符号直接挂。占位符按你的 so 替换。

```javascript
// hook_jni.js —— frida -U -f [包名] -l hook_jni.js --no-pause
// 或用 attach：frida -U [包名] -l hook_jni.js

const SO_NAME = "[libxxx.so]";          // 例如 libnative-lib.so
const JNI_EXPORT = "[Java_com_example_app_NativeCheck_verify]"; // 导出符号名

function ts() { return new Date().toISOString(); }
function log() { console.log.apply(console, [ts()].concat([].slice.call(arguments))); }

function hookJniExport() {
    const addr = Module.findExportByName(SO_NAME, JNI_EXPORT);
    if (addr === null) {
        log("[!] 未找到导出符号:", JNI_EXPORT, "在", SO_NAME);
        return;
    }
    log("[+] 命中:", JNI_EXPORT, "->", addr);

    Interceptor.attach(addr, {
        onEnter(args) {
            this.jniEnv = args[0];      // JNIEnv*
            this.thiz   = args[1];      // jobject / jclass
            // 后续参数从 args[2] 起，按 Java 方法签名解释
            log(">>> onEnter", JNI_EXPORT);
            log("    JNIEnv =", this.jniEnv, " this =", this.thiz);

            // 示例：Java 侧传入 String，取 UTF-8 明文
            // 需要 JavaVM 才能调用 JNI 函数，见下方 getJniEnv()
        },
        onLeave(retval) {
            log("<<< onLeave", JNI_EXPORT, "retval =", retval,
                "  (int?)", retval.toInt32());
        }
    });
}

// 拿 JNIEnv / JavaVM，用于读 jstring 等参数
let cachedEnv = null;
function getJniEnv() {
    if (cachedEnv !== null) return cachedEnv;
    const vmPtr = Module.findExportByName(null, "JNI_GetCreatedJavaVMs");
    if (vmPtr === null) return null;
    const vm = vmPtr.readPointer();
    // JavaVM* 的第一个函数指针是 GetEnv
    const vtable = vm.readPointer();
    const getEnvFn = vtable.readPointer();
    const GetEnv = new NativeFunction(getEnvFn, 'int', ['pointer', 'pointer', 'int']);
    const envBuf = Memory.alloc(Process.pointerSize);
    const r = GetEnv(vm, envBuf, 0x00010006); // JNI_VERSION_1_6
    if (r !== 0) return null;
    cachedEnv = envBuf.readPointer();
    return cachedEnv;
}

// 读 jstring 明文
function readJString(env, jstr) {
    if (jstr.isNull()) return "<null>";
    const GetStringUTFChars = new NativeFunction(
        env.readPointer().add(8 * 169).readPointer(), // 索引 169: GetStringUTFChars
        'pointer', ['pointer', 'pointer', 'pointer']
    );
    const ReleaseStringUTFChars = new NativeFunction(
        env.readPointer().add(8 * 170).readPointer(),
        'void', ['pointer', 'pointer', 'pointer']
    );
    const cstr = GetStringUTFChars(env, jstr, ptr(0));
    const s = cstr.readUtf8String();
    ReleaseStringUTFChars(env, jstr, cstr);
    return s;
}

function hookJniStringArgs() {
    const addr = Module.findExportByName(SO_NAME, JNI_EXPORT);
    if (addr === null) return;
    Interceptor.attach(addr, {
        onEnter(args) {
            const env = args[0];
            log(">>> 参数转储:", JNI_EXPORT);
            // 按签名逐个读；下面按 "[参数个数] 个 String" 举例
            try {
                log("    arg2(jstring) =", readJString(env, args[2]));
            } catch (e) {
                log("    读 arg2 失败:", e.message);
            }
            // 若是 jobjectArray，需用 GetObjectArrayElement 逐个取
        }
    });
}

setImmediate(function () {
    // 等 so 加载
    const dlopen = Module.findExportByName(null, "android_dlopen_ext");
    if (dlopen !== null) {
        Interceptor.attach(dlopen, {
            onEnter(args) {
                this.soPath = args[0].readCString();
            },
            onLeave(retval) {
                if (this.soPath && this.soPath.indexOf(SO_NAME) !== -1) {
                    log("[+] so 已加载:", this.soPath);
                    hookJniExport();
                    hookJniStringArgs();
                }
            }
        });
    } else {
        hookJniExport();
        hookJniStringArgs();
    }
});
```

