`dump_dex.js` 关键 hook 点（任选其一即可，组合更稳）：

```javascript
Java.perform(function () {
  var DexFile = Java.use("dalvik.system.DexFile");
  // 方案 A：DexFile 构造时 dump
  DexFile.$init.overload('java.lang.String').implementation = function (p) {
    var r = this.$init(p);
    dumpMem(p); // 读 /proc/self/maps 找 dex 魔数 64 65 78 0a 30 33 35 00
    return r;
  };
  // 方案 B：ART 层 DexFile::OpenMemory（更底层，壳改了上层也不怕）
  var openMem = Module.findExportByName("libart.so", "_ZN3art7DexFile10OpenMemoryEPKhmRKNSt3__112basic_stringIcNS3_11char_traitsIcEENS3_9allocatorIcEEEEjPNS_6MemMapEPKNS_7OatFileEPS9_");
  if (openMem) {
    Interceptor.attach(openMem, {
      onEnter: function (a) { this.base = a[0]; this.size = a[1].toInt32(); },
      onLeave: function () {
        if (this.size > 0x70 && this.base.readU32() === 0x0a786564) {
          var buf = Memory.readByteArray(this.base, this.size);
          send({type: "dex", size: this.size}, buf);
          // 再把 header 里 checksum/signature 重算，否则 IDA/jadx 打不开
        }
      }
    });
  }
});
```

**dump 产物修复（这一步跳过会导致 jadx 仍打不开）：**

```bash
# header 头 8 字节被抹时补 magic；重算 checksum 与 signature
python3 - <<'PY'
import zlib, hashlib, struct, sys
p = sys.argv[1] if len(sys.argv)>1 else "[dump.dex]"
b = bytearray(open(p,'rb').read())
b[0:8] = b'dex\n035\x00'
b[12:32] = hashlib.sha1(b[32:]).digest()
struct.pack_into('I', b, 8, zlib.adler32(bytes(b[12:])) & 0xffffffff)
open(p+'.fixed.dex','wb').write(b)
PY
```

