// aim_base.cpp — 目标: [进程名] (x64, UE4/UE5 通用骨架)
// 编译: cl /std:c++17 /EHsc aim_base.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <string>

DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return 0;
}

uint64_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uint64_t base = 0;
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { base = (uint64_t)me.modBaseAddr; break; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return base;
}

int main() {
    const wchar_t* PROC = L"[进程名]";     // ← 替换成实际进程名，例如 L"Game.exe"
    const wchar_t* MOD  = L"[模块名]";     // ← 通常是主模块名，例如 L"Game-Win64-Shipping.exe"

    DWORD pid = FindPid(PROC);
    if (!pid) { printf("[!] pid not found\n"); return 1; }
    uint64_t base = GetModuleBase(pid, MOD);
    printf("[+] pid=0x%X base=0x%llX\n", pid, base);

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("[!] OpenProcess failed %lu\n", GetLastError()); return 1; }

