**第二步：AOB 扫描 `GWorld` / `GObjects`（如果静态偏移不稳）**

```cpp
// 扫描特征：48 8B 05 ?? ?? ?? ?? 48 8B 88 ?? ?? ?? ?? 48 85 C9
uintptr_t FindGWorld(HANDLE h, uintptr_t base, size_t size) {
    auto buf = ReadBuffer(h, base, size);
    const uint8_t pat[] = {0x48,0x8B,0x05};
    for (size_t i = 0; i + 7 < size; ++i) {
        if (memcmp(buf.data()+i, pat, 3) == 0) {
            int32_t rel = *(int32_t*)(buf.data()+i+3);
            return base + i + 7 + rel; // RIP 相对寻址
        }
    }
    return 0;
}
```

**第三步：W2S + 自瞄角度**

```cpp
struct FVector { float X, Y, Z; };
struct FRotator { float Pitch, Yaw, Roll; };

bool WorldToScreen(const FVector& world, const FVector& camLoc, const FRotator& camRot,
                   float fov, int sw, int sh, FVector2D& out) {
    FVector d = world - camLoc;
    // 转相机空间（yaw/pitch 逆变换）
    float cp = cosf(camRot.Pitch * PI/180), sp = sinf(camRot.Pitch * PI/180);
    float cy = cosf(camRot.Yaw * PI/180),   sy = sinf(camRot.Yaw * PI/180);
    FVector fwd = { cp*cy, cp*sy, sp };
    FVector right = { -sy, cy, 0 };
    FVector up = { -sp*cy, -sp*sy, cp };
    float z = d.X*fwd.X + d.Y*fwd.Y + d.Z*fwd.Z;
    if (z < 1.f) return false;
    float x = d.X*right.X + d.Y*right.Y + d.Z*right.Z;
    float y = d.X*up.X + d.Y*up.Y + d.Z*up.Z;
    float f = (sw * 0.5f) / tanf(fov * PI/360.f);
    out.X = sw*0.5f + x * f / z;
    out.Y = sh*0.5f - y * f / z;
    return true;
}

FRotator CalcAngle(FVector src, FVector dst) {
    FVector d = dst - src;
    float hyp = sqrtf(d.X*d.X + d.Y*d.Y);
    return { atan2f(d.Z, hyp) * 180/PI, atan2f(d.Y, d.X) * 180/PI, 0 };
}

