```c
// rw.h —— 控制码与请求结构（用户态/内核态共用）
#pragma once
#include <ntdef.h>

#define RW_DEVICE_NAME   L"\\Device\\eac_rw"
#define RW_SYMLINK_NAME  L"\\DosDevices\\eac_rw"

#define IOCTL_RW_READ   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_RW_WRITE  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_RW_BASE   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS) // 取模块基址

typedef struct _RW_REQUEST {
    ULONG  Pid;         // 目标 [进程名].exe 的 PID
    PVOID  Address;     // 目标地址（模块基址 + [偏移]）
    PVOID  Buffer;      // 用户态缓冲区
    SIZE_T Size;
    WCHAR  ModuleName[64]; // BASE 用，如 L"game.exe"
    PVOID  BaseOut;
} RW_REQUEST, *PRW_REQUEST;
```

```c
// rw.c —— DriverEntry + 分发
#include <ntifs.h>
#include "rw.h"

static PDRIVER_OBJECT g_Driver;
static PDEVICE_OBJECT g_Device;

// MDL 方式读，绕开跨进程 Agent 权限限制；失败回退 MmCopyVirtualMemory
NTSTATUS KernelRead(PEPROCESS src, PVOID addr, PVOID buf, SIZE_T size) {
    MM_COPY_ADDRESS ca; ca.VirtualAddress = addr;
    SIZE_T done = 0;
    return MmCopyMemory(buf, ca, size, MM_COPY_MEMORY_VIRTUAL, &done);
}

NTSTATUS KernelWrite(PEPROCESS dst, PVOID addr, PVOID buf, SIZE_T size) {
    SIZE_T done = 0;
    return MmCopyVirtualMemory(PsGetCurrentProcess(), buf, dst, addr, size, KernelMode, &done);
}

static NTSTATUS Dispatch(PDEVICE_OBJECT dev, PIRP irp) {
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    PVOID in = irp->AssociatedIrp.SystemBuffer;
    ULONG inLen = sp->Parameters.DeviceIoControl.InputBufferLength;

    if (in && inLen >= sizeof(RW_REQUEST)) {
        PRW_REQUEST r = (PRW_REQUEST)in;
        PEPROCESS proc = NULL;
        if (NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)r->Pid, &proc))) {
            if (sp->Parameters.DeviceIoControl.IoControlCode == IOCTL_RW_READ)
                st = KernelRead(proc, r->Address, r->Buffer, r->Size);
            else if (sp->Parameters.DeviceIoControl.IoControlCode == IOCTL_RW_WRITE)
                st = KernelWrite(proc, r->Address, r->Buffer, r->Size);
            ObDereferenceObject(proc);
        } else st = STATUS_INVALID_PARAMETER;
    }
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = NT_SUCCESS(st) ? inLen : 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg) {
    UNICODE_STRING devName, symName;
    RtlInitUnicodeString(&devName, RW_DEVICE_NAME);
    RtlInitUnicodeString(&symName, RW_SYMLINK_NAME);
    NTSTATUS st = IoCreateDevice(drv, 0, &devName, FILE_DEVICE_UNKNOWN, FILE_DEVICE_SECURE_OPEN, FALSE, &g_Device);
    if (!NT_SUCCESS(st)) return st;
    IoCreateSymbolicLink(&symName, &devName);
    drv->MajorFunction[IRP_MJ_CREATE]  = Dispatch;
    drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = Dispatch;
    g_Driver = drv;
    return STATUS_SUCCESS;
}
```

