**驱动侧 `RwDrv.c`**

```c
#include <ntifs.h>

#define DEV_NAME  L"\\Device\\RwDrv"
#define SYM_NAME  L"\\DosDevices\\RwDrv"
#define IOCTL_READ  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_WRITE CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQ {
    ULONG  Pid;
    ULONG  Pad;
    PVOID  Addr;      // 目标进程内地址
    PVOID  Buffer;    // 调用方缓冲区（用户态地址）
    SIZE_T Size;
    SIZE_T Done;
} RW_REQ, *PRW_REQ;

static NTSTATUS DoRead(PRW_REQ r)
{
    PEPROCESS ep = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)r->Pid, &ep);
    if (!NT_SUCCESS(st)) return st;

    SIZE_T copied = 0;
    st = MmCopyVirtualMemory(ep, r->Addr, PsGetCurrentProcess(), r->Buffer, r->Size,
                             KernelMode, &copied);
    ObDereferenceObject(ep);
    r->Done = copied;
    return st;
}

static NTSTATUS DoWrite(PRW_REQ r)
{
    PEPROCESS ep = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)r->Pid, &ep);
    if (!NT_SUCCESS(st)) return st;

    // 写入方向：源 = 调用方缓冲区，目的 = 目标进程
    SIZE_T copied = 0;
    st = MmCopyVirtualMemory(PsGetCurrentProcess(), r->Buffer, ep, r->Addr, r->Size,
                             KernelMode, &copied);
    ObDereferenceObject(ep);
    r->Done = copied;
    return st;
}

static NTSTATUS Dispatch(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    PRW_REQ req = (PRW_REQ)irp->AssociatedIrp.SystemBuffer;

    if (req && sp->Parameters.DeviceIoControl.InputBufferLength >= sizeof(RW_REQ)) {
        switch (sp->Parameters.DeviceIoControl.IoControlCode) {
        case IOCTL_READ:  st = DoRead(req);  break;
        case IOCTL_WRITE: st = DoWrite(req); break;
        }
    }
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = (st == STATUS_SUCCESS) ? sizeof(RW_REQ) : 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

static VOID Unload(PDRIVER_OBJECT drv)
{
    UNICODE_STRING sym;
    RtlInitUnicodeString(&sym, SYM_NAME);
    IoDeleteSymbolicLink(&sym);
    IoDeleteDevice(drv->DeviceObject);
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg)
{
    UNREFERENCED_PARAMETER(reg);
    UNICODE_STRING devName, symName;
    PDEVICE_OBJECT dev = NULL;
    RtlInitUnicodeString(&devName, DEV_NAME);
    RtlInitUnicodeString(&symName, SYM_NAME);

    NTSTATUS st = IoCreateDevice(drv, 0, &devName, FILE_DEVICE_UNKNOWN, 0, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;

    st = IoCreateSymbolicLink(&symName, &devName);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(dev); return st; }

    drv->MajorFunction[IRP_MJ_CREATE] = Dispatch;
    drv->MajorFunction[IRP_MJ_CLOSE]  = Dispatch;
    drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = Dispatch;
    drv->DriverUnload = Unload;
    return STATUS_SUCCESS;
}
```

