```

偏移要在你的目标版本上用 WinDbg 核对：

```
kd> dt nt!_KPROCESS DirectoryTableBase
kd> dt nt!_EPROCESS Pcb.DirectoryTableBase
```

`DirectoryTableBase` 在 19041–19045 都是 `0x28`，1709 之前是 `0x28` 但低 12 位是 PCID 标志位，切换前必须掩掉低 12 位（见下面 `SwitchToProcess`）。

## 2. 驱动骨架

```c
// cr3rw.c — WDM 驱动，x64
#include <ntifs.h>
#include <ntddk.h>

#define DEVICE_NAME     L"\\Device\\Cr3Rw"
#define DOS_DEVICE_NAME L"\\DosDevices\\Cr3Rw"

#define CR3_OFFSET_IN_KPROCESS  0x28
#define PAGE_MASK               0xFFFFFFFFFFFFF000ULL

typedef struct _CR3_CTX {
    UINT64 OriginalCr3;
    UINT64 TargetCr3;
    KIRQL  OldIrql;
} CR3_CTX;

// ---------- CR3 切换 ----------
static
UINT64
ReadCr3(VOID)
{
    UINT64 cr3;
    __asm {
        mov rax, cr3
        mov cr3, rax
        mov cr3, rax
    }
    // 用 intrinsic 写法更干净：
    // cr3 = __readcr3();
    return cr3;
}

static
UINT64
GetProcessCr3(PEPROCESS Process)
{
    UINT64 dirBase = *(UINT64*)((PUCHAR)Process + CR3_OFFSET_IN_KPROCESS);
    return dirBase & PAGE_MASK;   // 掩掉低 12 位 PCID/标志
}

// 关中断 + 切 CR3，返回旧值
static
VOID
SwitchToProcess(CR3_CTX* Ctx, PEPROCESS Process)
{
    Ctx->TargetCr3 = GetProcessCr3(Process);
    Ctx->OldIrql = KeRaiseIrqlToDpcLevel();
    _disable();
    Ctx->OriginalCr3 = __readcr3() & PAGE_MASK;
    __writecr3(Ctx->TargetCr3);
}

static
VOID
RestoreCr3(CR3_CTX* Ctx)
{
    __writecr3(Ctx->OriginalCr3);
    _enable();
    KeLowerIrql(Ctx->OldIrql);
}
```

`__readcr3()` / `__writecr3()` 是 `<intrin.h>` 里的 intrinsic，比内联汇编干净：

```c
#include <intrin.h>
```

## 3. 物理地址 → 虚拟地址映射读写

CR3 切换只让**当前 CPU** 的页表指向目标进程。切过去后，用 `MmGetPhysicalAddress` 拿到的物理地址是目标进程的物理页。要读写，先把物理页映射到当前内核空间：

```c
static
PVOID
MapPhysicalPage(PHYSICAL_ADDRESS Phys, SIZE_T Size)
{
    // MmMapIoSpaceEx 对普通 RAM 页要带 MEMORY_CACHING
    PHYSICAL_ADDRESS aligned = {0};
    aligned.QuadPart = Phys.QuadPart & PAGE_MASK;
    SIZE_T mapSize = Size + (SIZE_T)(Phys.QuadPart & 0xFFF);
    mapSize = (mapSize + 0xFFF) & ~0xFFFULL;
    return MmMapIoSpaceEx(aligned, mapSize, PAGE_READWRITE | PAGE_NOCACHE);
}

static
VOID
UnmapPhysicalPage(PVOID Va, SIZE_T Size)
{
    SIZE_T mapSize = (Size + 0xFFF) & ~0xFFFULL;
    MmUnmapIoSpace(Va, mapSize);
}
```

