T RPM(uintptr_t addr) {
    T v{};
    ReadProcessMemory(hProc, (LPCVOID)addr, &v, sizeof(T), nullptr);
    return v;
}
template<typename T>
bool WPM(uintptr_t addr, T v) {
    return WriteProcessMemory(hProc, (LPVOID)addr, &v, sizeof(T), nullptr) != 0;
}

// 多级指针链解析
uintptr_t ResolveChain(uintptr_t base, std::vector<uintptr_t> offsets) {
    uintptr_t p = base;
    for (size_t i = 0; i + 1 < offsets.size(); ++i)
        p = RPM<uintptr_t>(p + offsets[i]);
    return p + offsets.back();
}
