// attach_target.c —— 打开目标进程并枚举模块基址（x64）
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

static DWORD find_pid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe = { .dwSize = sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static ULONG_PTR module_base(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me = { .dwSize = sizeof(me) };
    ULONG_PTR base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (!_wcsicmp(me.szModule, mod)) { base = (ULONG_PTR)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int main(void) {
    const wchar_t* PROC = L"[进程名].exe";   // ← 换成目标进程名
    const wchar_t* MOD  = L"[模块名].exe";   // ← 换成目标模块名
    DWORD pid = find_pid(PROC);
    if (!pid) { printf("pid not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ |
                           PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
    if (!h) { printf("OpenProcess failed: %lu\n", GetLastError()); return 1; }

    ULONG_PTR base = module_base(pid, MOD);
    printf("pid=%lu base=0x%llX\n", pid, (unsigned long long)base);
    CloseHandle(h);
    return 0;
}
