### 2. 世界到屏幕（W2S）

```c
typedef struct { float x, y, z; } FVector;
typedef struct { float x, y, z; } FRotator;

bool WorldToScreen(FVector world, FVector camLoc, FRotator camRot,
                   float fov, int screenW, int screenH, FVector2D *out) {
    // UE 坐标系: X 前 Y 右 Z 上
    double dx = world.x - camLoc.x;
    double dy = world.y - camLoc.y;
    double dz = world.z - camLoc.z;

    double cp = cos(camRot.Pitch * M_PI / 180.0);
    double sp = sin(camRot.Pitch * M_PI / 180.0);
    double cy = cos(camRot.Yaw   * M_PI / 180.0);
    double sy = sin(camRot.Yaw   * M_PI / 180.0);
    double cr = cos(camRot.Roll  * M_PI / 180.0);
    double sr = sin(camRot.Roll  * M_PI / 180.0);

    // 旋转矩阵（UE 顺序：Roll → Pitch → Yaw）
    double F[3] = { cp*cy, cp*sy, sp };
    double R[3] = { sr*sp*cy - cr*sy, sr*sp*sy + cr*cy, -sr*cp };
    double U[3] = { -(cr*sp*cy + sr*sy), -(cr*sp*sy - sr*cy), cr*cp };

    double f = dx*F[0] + dy*F[1] + dz*F[2];
    if (f <= 0.01) return false;
    double r = dx*R[0] + dy*R[1] + dz*R[2];
    double u = dx*U[0] + dy*U[1] + dz*U[2];

    double tv = tan(fov * M_PI / 360.0);
    out->x = (float)(screenW * 0.5 * (1.0 + r / (tv * f)));
    out->y = (float)(screenH * 0.5 * (1.0 - u / (tv * f)));
    return true;
}
```

